using System;
using System.Collections.Generic;
using System.Linq;
using System.Web;
using System.Web.UI;
using System.Web.UI.WebControls;
using System.Data;
using System.Collections;
using System.Globalization;
using WebGlobal;
using SimsObject;

namespace InformationWeb.Controls.ScheduleChecking
{
    public partial class List : ControlBase
    {
        #region Properties

        private string SortBy
        {
            set { ViewState["SortBy"] = value; }
            get
            {
                if (ViewState["SortBy"] != null) return ViewState["SortBy"].ToString();
                return null;
            }
        }

        private string SortDesc
        {
            set { ViewState["SortDesc"] = value; }
            get
            {
                if (ViewState["SortDesc"] != null) return ViewState["SortDesc"].ToString();
                return null;
            }
        }


        public long? ClassSubjectID
        {
            get
            {
                if (ViewState["ClassSubjectID" + this.ClientID] != null)
                    return Convert.ToInt64(ViewState["ClassSubjectID" + this.ClientID]);
                return null;
            }
            set { ViewState["ClassSubjectID" + this.ClientID] = value; }
        }

        public String ClassID
        {
            get
            {
                if (ViewState["ClassID" + this.ClientID] != null)
                    return ViewState["ClassID" + this.ClientID].ToString();
                return null;
            }
            set { ViewState["ClassID" + this.ClientID] = value; }
        }

        #endregion

        protected int intRowIndex = 0; // thứ tự row
        private bool bolIsLocked = false;
        private DataTable dtbData = null;
        protected string strFilePath_Logis = "";

        /// <summary>
        /// Số tiết từ store có thể là decimal(5,1) ("2.0") — không dùng Convert.ToInt32.
        /// </summary>
        private decimal? ParseQuantityFromHidden(string value)
        {
            if (value == null)
                return null;
            string str = value.Trim();
            if (str == "")
                return null;
            decimal decValue;
            if (decimal.TryParse(str, NumberStyles.Any, CultureInfo.InvariantCulture, out decValue))
                return decValue;
            if (decimal.TryParse(str, NumberStyles.Any, CultureInfo.CurrentCulture, out decValue))
                return decValue;
            return null;
        }

        private void LoadData(string sortExpression = null)
        {
            if (User == null)
            {
                MsgBox.ShowError("Bạn chưa đăng nhập hệ thống!");
                return;
            }
            if (this.ClassSubjectID == null)
            {
                MsgBox.ShowError("Bạn chưa chọn môn học lớp!");
                return;
            }

            SIM_ScheduleChecking obj = new SIM_ScheduleChecking();

            #region  Lấy classsubject info

            DataTable dtb = obj.GetDataTable("SIM_Class_Subject_GetInfo", "@ClassSubjectID", this.ClassSubjectID);
            if (dtb != null && dtb.Rows.Count > 0)
            {
                this.ClassID = dtb.Rows[0]["ClassID"].ToString();
                bolIsLocked = Convert.ToBoolean(dtb.Rows[0]["IsLocked"]);

                lblClassSubjectName.Text = "<b>" + dtb.Rows[0]["SubjectName"].ToString() + "</b> - Mã lớp: <b>" + dtb.Rows[0]["ClassID"].ToString()
                                        + "</b> - Niên học: <b>" + dtb.Rows[0]["YearID"].ToString() + " - " + (Convert.ToInt32(dtb.Rows[0]["YearID"]) + 1).ToString() + "</b> - Học kì: <b>" + dtb.Rows[0]["Semester"].ToString()
                                        + (bolIsLocked ? "<span style='color:Red'> (ĐÃ KHOÁ SỔ ĐIỂM) </span>" : "")
                                        + "</b>";

                lblTeacher.Text = dtb.Rows[0]["TeacherName"].ToString();
            }
            else
            {
                lblClassSubjectName.Text = "Việc lấy thông tin môn học lớp bị lỗi!";
                lblTeacher.Text = "";
                return;
            }

            #endregion


            dtbData = obj.GetDataTable("SIM_ScheduleChecking_SearchForWeb",
                                        "@ClassSubjectID", this.ClassSubjectID,
                                        "@LoginName", User.UserName);

            if (dtbData != null)
            {
                rptList.DataSource = dtbData;
                rptList.DataBind();

                btnExportExcel.Visible = true;
                btnView_SubjectCheckingSummary.Visible = true;

                udpList.Update();
            }
            else
            {
                MsgBox.ShowError("Việc tải thông tin bị lỗi!");
            }
        }

        private bool SaveData()
        {
            return false;
        }

        private void ExportExcel()
        {
            Hashtable hstColumns = new Hashtable();
            Hashtable hstReplaceValues = new Hashtable();
            SIM_ScheduleChecking obj = new SIM_ScheduleChecking();

            #region  Lấy classsubject info

            DataTable dtb = obj.GetDataTable("SIM_Class_Subject_GetInfo", "@ClassSubjectID", this.ClassSubjectID);

            if (dtb != null && dtb.Rows.Count > 0)
            {
                DataRow drw = dtb.Rows[0];
                hstReplaceValues.Add("{Khoa}", drw["ScienceName"]);
                hstReplaceValues.Add("{Khóa}", drw["CourseName"]);
                hstReplaceValues.Add("{Lớp}", drw["ClassName"]);
                hstReplaceValues.Add("{Môn}", drw["SubjectName"]);
                hstReplaceValues.Add("{Giáo viên}", drw["TeacherName"] + "  (Từ ............... đến ...............)");
            }
            else
            {
                MsgBox.ShowError("Việc lấy thông tin môn học lớp bị lỗi!");
                return;
            }

            #endregion

            DataTable dtbExport = obj.GetDataTable("SIM_ScheduleChecking_SearchForWeb",
                                        "@ClassSubjectID", this.ClassSubjectID,
                                        "@LoginName", User.UserName);

            string strPath = System.Web.HttpContext.Current.Server.MapPath("~");
            string strFilePath = strPath + "Template\\So dau bai.xls";

            string strFileNameSaveAs = "So dau bai - " + User.UserName + ".xls";
            string strPathSaveAs = strPath + "Export\\" + strFileNameSaveAs;


            string[] cols = { "DateText", "TheoryQuantity", "PracticeQuantity", "TestQuantity", "LearningContent", "RequestContent", "OffStudentCount", "Description" };

            foreach (string str in cols)
                hstColumns.Add(str, str);

            if (Libs.CExcel.ExportTemplateExcel(dtbExport, strFilePath, "DateText", hstColumns, hstReplaceValues, strPathSaveAs))
            {
                Response.Redirect("/Export/" + strFileNameSaveAs);
            }
            else
            {
                MsgBox.ShowError("Việc xuất excel thất bại");
            }
        }

        #region Protected Functions

        protected string GetCssName(string fieldName)
        {
            if (this.SortBy == fieldName)
            {
                if (this.SortDesc == "Desc")
                    return "Title-Desc";
                return "Title-Asc";
            }
            return "";
        }

        protected string WriteEventRow()
        {
            intRowIndex++;
            if (intRowIndex % 2 == 0)
                return " class='RowAlt' ";
            return " class='Row' ";
        }

        private void GetDefault()
        {
            strFilePath_Logis = DCore.Globals.GetConfig("LogicalDirectory_Upload") + "/Data/ScheduleChecking/";
            try
            {
                if (Request["csid"] != null && Request["csid"].ToString() != "")
                    this.ClassSubjectID = Convert.ToInt64(Request["csid"]);
                if (Request["cid"] != null && Request["cid"].ToString() != "")
                    this.ClassID = Request["cid"].ToString();
            }
            catch
            {
                lblClassSubjectName.Text = "Không tìm thấy môn học lớp!";
            }
        }

        protected bool AllowEdit(object teacherIDOfSchedule)
        {
            if (bolIsLocked)
                return false;

            if (User == null)
                return false;

            return true;
        }

        #endregion

        private void uClassSubject_SearchClick(object classSubjectID, object teacherID_Schedule, object teacherName_Schedule)
        {
            btnExportExcel.Visible = btnView_SubjectCheckingSummary.Visible = false;
            uSubjectChecking.Visible = false;

            if (classSubjectID != null)
            {
                this.ClassSubjectID = Convert.ToInt64(classSubjectID);
                LoadData();
                udpSubjectChecking.Update();
            }
        }

        protected void Page_Load(object sender, EventArgs e)
        {
            GetDefault();
            uClassSubject.SearchClick += new Controls.Sims.UClassSubject_ForSchedule.SearchDelegate(uClassSubject_SearchClick);

            if (!IsPostBack)
            {
                if (User == null)
                {
                    MsgBox.ShowWarning("Chức năng này chỉ dành cho nhà quản lý hoặc giảng viên, vui lòng đăng nhập để nhập dữ liệu!");
                    Response.Redirect("~/");
                }
            }

            uEdit.SavedCompleted += new EventHandler(uEdit_SavedCompleted);
        }

        protected void lbtTitle_Click(object sender, EventArgs e)
        {
            LinkButton lbt = sender as LinkButton;
            this.SortBy = lbt.CommandArgument;
            if (this.SortDesc == "Asc")
                this.SortDesc = "Desc";
            else
                this.SortDesc = "Asc";
            LoadData();
        }

        protected void btnSearch_Click(object sender, EventArgs e)
        {
            LoadData();
        }

        protected void lbtEdit_Click(object sender, EventArgs e)
        {
            LinkButton lbt = sender as LinkButton;
            uEdit.Clear();
            if (lbt.CommandArgument != "")
            {
                uEdit.LoadInfo(Convert.ToInt64(lbt.CommandArgument));
                uEdit.ShowPopup();
            }
            else
            {
                int intIndex = Convert.ToInt32(lbt.ToolTip);
                RepeaterItem rptItem = rptList.Items[intIndex];

                HiddenField hidTeacherIDOfSchedule = rptItem.FindControl("hidTeacherIDOfSchedule") as HiddenField;
                HiddenField hidTheoryQuantity = rptItem.FindControl("hidTheoryQuantity") as HiddenField;
                HiddenField hidPracticeQuantity = rptItem.FindControl("hidPracticeQuantity") as HiddenField;
                HiddenField hidTestQuantity = rptItem.FindControl("hidTestQuantity") as HiddenField;
                HiddenField hidSession = rptItem.FindControl("hidSession") as HiddenField;

                uEdit.ClassSubjectID = this.ClassSubjectID;
                uEdit.Date = Convert.ToDateTime(lbt.CommandName);
                if (hidSession != null && !string.IsNullOrWhiteSpace(hidSession.Value))
                    uEdit.SessionID = Convert.ToInt32(hidSession.Value.Trim());
                uEdit.TeacherID = hidTeacherIDOfSchedule.Value;

                decimal? decTheory = ParseQuantityFromHidden(hidTheoryQuantity.Value);
                if (decTheory != null)
                    uEdit.TheoryQuantity = decTheory;
                decimal? decPractice = ParseQuantityFromHidden(hidPracticeQuantity.Value);
                if (decPractice != null)
                    uEdit.PracticeQuantity = decPractice;
                decimal? decTest = ParseQuantityFromHidden(hidTestQuantity.Value);
                if (decTest != null)
                    uEdit.TestQuantity = decTest;

                uEdit.ShowPopup();
            }
        }

        protected void uEdit_SavedCompleted(object sender, EventArgs e)
        {
            LoadData();
        }


        protected void lbtSubjectChecking_Click(object sender, EventArgs e)
        {
            LinkButton lbt = sender as LinkButton;
            uSubjectChecking.ClassSubjectID = this.ClassSubjectID;
            uSubjectChecking.Date = Convert.ToDateTime(lbt.CommandName);
            uSubjectChecking.SessionID = Convert.ToInt32(lbt.CommandArgument);
            uSubjectChecking.ClassID = this.ClassID;
            uSubjectChecking.LoadData();
            uSubjectChecking.Visible = true;
            udpSubjectChecking.Update();
            ScriptManager.RegisterStartupScript(Page, typeof(string), "_initEnterToTab2", "EnterToTab2.init()", true);
        }

        protected void rptList_ItemDataBound(object sender, RepeaterItemEventArgs e)
        {
            if (e.Item.ItemIndex >= 0)
            {
                LinkButton lbt = e.Item.FindControl("lbtEdit") as LinkButton;
                lbt.ToolTip = e.Item.ItemIndex.ToString();
            }
        }

        protected void btnExportExcel_Click(object sender, EventArgs e)
        {
            ExportExcel();
        }

        protected void btnView_SubjectCheckingSummary_Click(object sender, EventArgs e)
        {
            Response.Redirect("SubjectCheckingSummary.aspx?csid=" + WebGlobal.EncodeRequest(this.ClassSubjectID.ToString()));
        }

        protected string GetLink(object contentFile)
        {
            if (contentFile != null && contentFile.ToString() != "")
            {
                return "<br><a style='color:blue' target='_blank' href='" + strFilePath_Logis + contentFile + "'>Tải tập tin</a>";
            }
            return "";
        }
    }
}

